<script setup lang="ts">
import{ref}from 'vue';import{api}from '@/api/client';const email=ref('');const message=ref('');const error=ref('');const busy=ref(false);async function submit(){busy.value=true;error.value='';try{const r=await api.post('/auth/forgot-password',{email:email.value});message.value=r.data.message??'If the account exists, a reset link has been sent.'}catch(e:any){error.value=e.response?.data?.message??'Could not request reset.'}finally{busy.value=false}}</script>
<template><main class="login-page"><section class="login-panel"><RouterLink class="brand" to="/login"><span class="brand-mark">C</span> Court Hub</RouterLink><p class="eyebrow">PASSWORD RECOVERY</p><h1>Reset your password.</h1><form @submit.prevent="submit"><label>Email<input v-model="email" type="email"/></label><p v-if="message" class="action-message success">{{message}}</p><p v-if="error" class="form-error">{{error}}</p><button class="primary-button" :disabled="busy">Send reset link</button></form><p class="login-note"><RouterLink to="/login">Back to sign in</RouterLink></p></section><section class="login-art"><div><h2>We’ll help you get back in.</h2></div></section></main></template>
